import type { ClaudeRateLimitState } from '../../services/agents/claude_rate_limit_service'

const CLAUDE_RATE_LIMIT_WARNING_PERCENT = 80

/** Derives Claude usage visibility and attention state for both status surfaces. */
export function claudeRateLimitPresentation(state: ClaudeRateLimitState) {
    const { receivedAt, snapshot, stale } = state
    if (!snapshot?.available || receivedAt === null || stale || snapshot.windows.length === 0) return null
    const highestUsedPercent = Math.max(...snapshot.windows.map(({ usedPercent }) => usedPercent))
    const reached = highestUsedPercent >= 100
    const nearLimit = !reached && highestUsedPercent >= CLAUDE_RATE_LIMIT_WARNING_PERCENT

    return {
        accessibleState: reached ? ', limit reached' : nearLimit ? ', near limit' : '',
        highestUsedPercent,
        nearLimit,
        reached,
        receivedAt,
        snapshot,
    }
}

import SpeedOutlined from '@mui/icons-material/SpeedOutlined'
import { Button } from '@mui/material'
import { useEffect, useState, type MouseEvent } from 'react'
import { useClaudeRateLimits } from '../hooks/use_claude_rate_limits'
import { ClaudeRateLimitDetails } from './claude_rate_limit_details'
import { claudeRateLimitPresentation } from './claude_rate_limit_status_data'
import { MobileStatusRow } from './mobile_status_row'
import { StatusDetailsSurface } from './status_details_surface'

const RESET_CLOCK_UPDATE_INTERVAL_MS = 30_000

interface ClaudeRateLimitStatusProps {
    mobile?: boolean
}

/** Account-wide Claude rate-limit status. Own subscription stays at this leaf boundary. */
export function ClaudeRateLimitStatus({ mobile = false }: ClaudeRateLimitStatusProps) {
    const rateLimitState = useClaudeRateLimits()
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const [currentTime, setCurrentTime] = useState(Date.now)

    useEffect(() => {
        const interval = setInterval(() => setCurrentTime(Date.now()), RESET_CLOCK_UPDATE_INTERVAL_MS)

        return () => clearInterval(interval)
    }, [])

    const presentation = claudeRateLimitPresentation(rateLimitState)
    if (!presentation) return null
    const { accessibleState, highestUsedPercent, nearLimit, reached, receivedAt, snapshot } = presentation
    const statusColor = reached ? 'error.main' : nearLimit ? 'warning.main' : 'text.secondary'
    const roundedHighestPercent = Math.round(highestUsedPercent)
    const openDetails = (event: MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }
    const closeDetails = () => {
        setAnchorElement(null)
    }
    const accessibleName = `Claude usage ${roundedHighestPercent}% used${accessibleState}`

    return (
        <>
            {mobile ? (
                <MobileStatusRow
                    accessibleName={accessibleName}
                    icon={<SpeedOutlined sx={{ fontSize: 18 }} />}
                    label="Claude usage"
                    onClick={openDetails}
                    tone={statusColor}
                    value={`${roundedHighestPercent}% used`}
                />
            ) : (
                <Button
                    aria-label={accessibleName}
                    onClick={openDetails}
                    size="small"
                    startIcon={<SpeedOutlined sx={{ fontSize: 14 }} />}
                    sx={{ color: statusColor, fontSize: 'inherit', minWidth: 0, p: 0.5, whiteSpace: 'nowrap' }}
                >
                    Claude {roundedHighestPercent}% used
                </Button>
            )}
            <StatusDetailsSurface anchorElement={anchorElement} labelId="claude-rate-limit-title" mobile={mobile} onClose={closeDetails}>
                <ClaudeRateLimitDetails
                    currentTime={currentTime}
                    reached={reached}
                    receivedAt={receivedAt}
                    snapshot={snapshot}
                />
            </StatusDetailsSurface>
        </>
    )
}

import { Box, Divider, Stack, Typography } from '@mui/material'
import type {
    ClaudeRateLimitSnapshot,
    ClaudeRateLimitWindow,
    ClaudeRateLimitWindowId,
} from '../../data/electron_claude_runtime_bridge'

const POPOVER_WIDTH = 360
const WINDOW_LABELS: Record<ClaudeRateLimitWindowId, string> = { five_hour: 'Session', weekly: 'Weekly' }

function formatReset(resetTime: number, observedAt: number, receivedAt: number, currentTime: number) {
    const localResetTime = receivedAt + resetTime - observedAt
    const remainingMilliseconds = Math.max(0, localResetTime - currentTime)
    const remainingMinutes = Math.ceil(remainingMilliseconds / 60_000)
    const localTime = new Date(localResetTime).toLocaleString([], {
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        month: 'short',
    })

    return `Resets ${localTime} (${remainingMinutes} min)`
}

function windowDetail(window: ClaudeRateLimitWindow, observedAt: number, receivedAt: number, currentTime: number) {
    return `${WINDOW_LABELS[window.id]}: ${Math.round(window.usedPercent)}% used Â· ${formatReset(window.resetsAt, observedAt, receivedAt, currentTime)}`
}

interface ClaudeRateLimitDetailsProps {
    currentTime: number
    reached: boolean
    receivedAt: number
    snapshot: ClaudeRateLimitSnapshot
}

/** Claude-specific limit details shared by desktop popover and mobile dialog. */
export function ClaudeRateLimitDetails(props: ClaudeRateLimitDetailsProps) {
    const { currentTime, reached, receivedAt, snapshot } = props

    return (
        <Box sx={{ maxHeight: 'calc(100vh - 16px)', maxWidth: 'calc(100vw - 16px)', overflow: 'auto', width: POPOVER_WIDTH }}>
            <Box sx={{ p: 2 }}>
                <Typography id="claude-rate-limit-title" component="h2" sx={{ color: 'text.primary', fontWeight: 700 }} variant="subtitle2">
                    Claude account limits
                </Typography>
                {reached ? <Typography color="error.main" role="status" variant="caption">Claude limit reached</Typography> : null}
            </Box>
            <Divider />
            <Stack divider={<Divider flexItem />}>
                {snapshot.windows.map((window) => (
                    <Typography color="text.secondary" key={window.id} sx={{ p: 2 }} variant="caption">
                        {windowDetail(window, snapshot.observedAt, receivedAt, currentTime)}
                    </Typography>
                ))}
            </Stack>
        </Box>
    )
}

