9	const USAGE_OUTPUT = `You are currently using your subscription to power your Claude Code usage
10	
11	Current session: 17% used · resets Aug 15, 9:49pm (Europe/Brussels)
12	Current week (all models): 13% used · resets Aug 16, 6:59pm (Europe/Brussels)
13	`;
14	
15	function completedChild(output = USAGE_OUTPUT, exitCode = 0) {
16	    const child = new EventEmitter();
17	    child.stdin = new PassThrough();
18	    child.stdout = new PassThrough();
19	    child.stderr = new PassThrough();
20	    queueMicrotask(() => {
21	        child.stdout.write(output);
22	        child.stdout.end();
23	        child.emit('close', exitCode);
24	    });
25	
26	    return child;
27	}
